// Post-build prune: remove UNREFERENCED raster image originals from dist/_astro.
//
// Why: Vite/Astro emits every imported source image (content collections
// `image()` schema + `import.meta.glob` galleries) into dist/_astro even when
// only the optimized variants generated by `getImage()`/`<Image>` are actually
// referenced. Multi-MB gallery/cover originals would otherwise ship to prod
// (~150 MB of orphans).
//
// Safety model:
// - Only touches `dist/_astro`, only raster extensions (.jpg/.jpeg/.png/.webp/
//   .avif/.gif). Never JS/CSS/fonts/SVG.
// - A file is kept if its (URL-decoded) basename appears in ANY text output
//   (html/js/css/json/xml/txt/webmanifest) — srcset entries, island props,
//   JSON-LD, og:meta all count.
// - Aborts without deleting if no reference at all is found (parsing bug guard).
import { promises as fs } from "node:fs";
import path from "node:path";

const DIST_DIR = path.resolve("dist");
const ASSETS_DIR = path.join(DIST_DIR, "_astro");
const TEXT_EXTENSIONS = new Set([
  ".html",
  ".js",
  ".mjs",
  ".css",
  ".json",
  ".xml",
  ".txt",
  ".webmanifest",
]);
const PRUNABLE_EXTENSIONS = new Set([
  ".jpg",
  ".jpeg",
  ".png",
  ".webp",
  ".avif",
  ".gif",
]);

async function walk(dir) {
  const entries = await fs.readdir(dir, { withFileTypes: true });
  const files = await Promise.all(
    entries.map((entry) => {
      const fullPath = path.join(dir, entry.name);
      return entry.isDirectory() ? walk(fullPath) : [fullPath];
    }),
  );
  return files.flat();
}

function collectReferences(text, referenced) {
  // Match /_astro/<file>.<raster ext> — stops at the extension, so srcset
  // descriptors ("400w"), quotes and JSON escapes never leak into the name.
  const pattern = /\/_astro\/[^"'\s>()]+?\.(?:jpg|jpeg|png|webp|avif|gif)/gi;
  for (const match of text.matchAll(pattern)) {
    const rawName = match[0].slice("/_astro/".length);
    referenced.add(rawName);
    try {
      referenced.add(decodeURIComponent(rawName));
    } catch {
      // Keep the raw form only if the URL decoding fails.
    }
  }
}

const allFiles = await walk(DIST_DIR);

const referenced = new Set();
for (const file of allFiles) {
  if (!TEXT_EXTENSIONS.has(path.extname(file).toLowerCase())) continue;
  collectReferences(await fs.readFile(file, "utf8"), referenced);
}

if (referenced.size === 0) {
  console.error(
    "[prune-dist-originals] No /_astro image reference found at all — " +
      "aborting without deleting anything (extraction probably broken).",
  );
  process.exit(1);
}

const candidates = allFiles.filter(
  (file) =>
    path.dirname(file) === ASSETS_DIR &&
    PRUNABLE_EXTENSIONS.has(path.extname(file).toLowerCase()),
);

let removedCount = 0;
let removedBytes = 0;
for (const file of candidates) {
  if (referenced.has(path.basename(file))) continue;
  const { size } = await fs.stat(file);
  await fs.unlink(file);
  removedCount += 1;
  removedBytes += size;
}

const freedMb = (removedBytes / (1024 * 1024)).toFixed(1);
console.log(
  `[prune-dist-originals] Removed ${removedCount} unreferenced image(s), ` +
    `freed ${freedMb} MB (kept ${candidates.length - removedCount} referenced).`,
);
